func TestRuntimeObserverRequiresConcreteClient(t *testing.T) {
	for _, ctx := range []context.Context{nil, t.Context()} {
		if _, err := (RuntimeObserver{}).Observe(ctx, RuntimePins{}); err == nil {
			t.Fatal("missing concrete runtime client accepted")
		}
	}
}

func TestRuntimeSpecRefusesAdmissionDrift(t *testing.T) {
	pins := RuntimePins{
		Process: runtimespec.Process{User: runtimespec.User{UID: 65534, GID: 65534}, Args: []string{"/terrabase"},
			Cwd: "/", NoNewPrivileges: true, Capabilities: &runtimespec.LinuxCapabilities{}},
		Resources: runtimespec.LinuxResources{Memory: &runtimespec.LinuxMemory{Limit: new(int64(64 << 20))}},
		Mounts:    []runtimespec.Mount{{Source: "/run/retained/volume", Destination: "/retained", Type: "bind", Options: []string{"rbind", "nosuid", "nodev", "noexec", "noatime"}}},
		Volume:    hostvolume.MountPins{MountPath: "/run/retained/volume"}, VolumeDestination: "/retained",
		Namespaces: []runtimespec.LinuxNamespace{{Type: runtimespec.PIDNamespace}, {Type: runtimespec.MountNamespace}},
	}
	makeSpec := func() *runtimespec.Spec {
		return &runtimespec.Spec{Root: &runtimespec.Root{Readonly: true}, Process: &pins.Process, Mounts: pins.Mounts,
			Linux: &runtimespec.Linux{CgroupsPath: "/terrascale/ts-member", Resources: &pins.Resources, Namespaces: slices.Clone(pins.Namespaces)}}
	}
	if err := verifyRuntimeSpec(makeSpec(), pins, "ts-member"); err != nil {
		t.Fatal(err)
	}
	for name, mutate := range map[string]func(*runtimespec.Spec){
		"writable root": func(spec *runtimespec.Spec) { spec.Root.Readonly = false },
		"different process": func(spec *runtimespec.Spec) {
			process := *spec.Process
			process.Args = []string{"/different-member"}
			spec.Process = &process
		},
		"different limits": func(spec *runtimespec.Spec) {
			spec.Linux.Resources = &runtimespec.LinuxResources{Memory: &runtimespec.LinuxMemory{Limit: new(int64(128 << 20))}}
		},
		"different mount": func(spec *runtimespec.Spec) {
			spec.Mounts = []runtimespec.Mount{{Source: "/run/another-volume", Destination: "/retained", Type: "bind"}}
		},
		"different cgroup":     func(spec *runtimespec.Spec) { spec.Linux.CgroupsPath = "/other" },
		"host PID namespace":   func(spec *runtimespec.Spec) { spec.Linux.Namespaces[0].Path = "/proc/1/ns/pid" },
		"host mount namespace": func(spec *runtimespec.Spec) { spec.Linux.Namespaces[1].Path = "/proc/1/ns/mnt" },
		"user namespace": func(spec *runtimespec.Spec) {
			spec.Linux.Namespaces = append(spec.Linux.Namespaces, runtimespec.LinuxNamespace{Type: runtimespec.UserNamespace})
		},
		"private network namespace": func(spec *runtimespec.Spec) {
			spec.Linux.Namespaces = append(spec.Linux.Namespaces, runtimespec.LinuxNamespace{Type: runtimespec.NetworkNamespace})
		},
	} {
		t.Run(name, func(t *testing.T) {
			spec := makeSpec()
			mutate(spec)
			if err := verifyRuntimeSpec(spec, pins, "ts-member"); err == nil {
				t.Fatal("actual runtime drift accepted")
			}
		})
	}
	if !reflect.DeepEqual(makeSpec().Process, &pins.Process) {
		t.Fatal("drift fixtures mutated admitted process pins")
	}
}

func TestDecide(t *testing.T) {
	cases := []struct {
		name        string
		fenced      bool
		attachments []Attachment
		mounted     bool
		want        StepKind
	}{
		{"unfenced never detaches", false, []Attachment{attachment("a", "old", "ATTACHED")}, false, StepProveFence},
		{"detach old attached", true, []Attachment{attachment("a", "old", "ATTACHED")}, false, StepDetach},
		{"detach old attaching", true, []Attachment{attachment("a", "old", "ATTACHING")}, false, StepDetach},
		{"wait detaching", true, []Attachment{attachment("a", "old", "DETACHING")}, false, StepWaitDetached},
		{"attach after detached history", true, []Attachment{attachment("a", "old", "DETACHED")}, false, StepAttach},
		{"attach with no history", true, nil, false, StepAttach},
		{"wait replacement", true, []Attachment{attachment("a", "old", "DETACHED"), attachment("b", "new", "ATTACHING")}, false, StepWaitAttached},
		{"grant mount", true, []Attachment{attachment("a", "old", "DETACHED"), attachment("b", "new", "ATTACHED")}, false, StepGrantMount},
		{"done", true, []Attachment{attachment("b", "new", "ATTACHED")}, true, StepDone},
		{"third instance holds", true, []Attachment{attachment("c", "0000000000V4MRM46HP1SNGDYW", "ATTACHED")}, false, StepHold},
		{"third instance detached is history", true, []Attachment{attachment("c", "0000000000V4MRM46HP1SNGDYW", "DETACHED")}, false, StepAttach},
		{"two replacement attachments hold", true, []Attachment{attachment("b", "new", "ATTACHED"), attachment("d", "new", "ATTACHING")}, false, StepHold},
		{"unknown old state holds", true, []Attachment{attachment("a", "old", "FAULTY")}, false, StepHold},
		{"other volume holds", true, []Attachment{{ID: "x", VolumeID: "vol-2", InstanceID: "new", State: "ATTACHED"}}, false, StepHold},
		{"old detach precedes replacement", true, []Attachment{attachment("b", "new", "ATTACHED"), attachment("a", "old", "ATTACHED")}, false, StepDetach},
	}
	for _, test := range cases {
		if got := Decide(request, test.fenced, test.attachments, test.mounted); got.Kind != test.want {
			t.Fatalf("%s: step %s (%s), want %s", test.name, got.Kind, got.Reason, test.want)
		}
	}
}

func TestProveFencedRequiresTerminated(t *testing.T) {
	now := time.Now()
	for state, ok := range map[string]bool{"TERMINATED": true, "TERMINATING": false, "STOPPED": false, "RUNNING": false} {
		proof, err := ProveFenced(t.Context(), fakeInstances{"old": state}, "old", now)
		if ok != (err == nil) || ok && proof.State != "TERMINATED" {
			t.Fatalf("%s: proof=%+v err=%v", state, proof, err)
		}
		if !ok && !errors.Is(err, storage.ErrWriterNotFenced) {
			t.Fatalf("%s: wrong error %v", state, err)
		}
	}
	if _, err := ProveFenced(t.Context(), fakeInstances{}, "old", now); !errors.Is(err, storage.ErrWriterNotFenced) {
		t.Fatalf("unobservable instance was fenced: %v", err)
	}
}

func TestReattacherDrivesTerminatedHostToMountedReplacement(t *testing.T) {
	instances := fakeInstances{"old": "RUNNING"}
	volumes := &fakeVolumes{attachments: []Attachment{attachment("a", "old", "ATTACHED")}}
	permits := &fakePermits{granted: map[string]bool{}}
	reattacher := Reattacher{Fencer: &fakeFencer{snapshot: leader()},
		Instances: instances, Volumes: volumes, Permits: permits}

	// A host that only stopped answering is never detached.
	if step, err := reattacher.Step(t.Context(), request); step.Kind != StepProveFence || !errors.Is(err, storage.ErrWriterNotFenced) || volumes.detaches != 0 {
		t.Fatalf("unfenced host was detached: %+v %v", step, err)
	}
	if volumes.listings != 0 {
		t.Fatalf("an unproven fence still listed attachments %d times", volumes.listings)
	}
	instances["old"] = "TERMINATED"
	want := []StepKind{StepDetach, StepWaitDetached}
	for _, kind := range want {
		step, err := reattacher.Step(t.Context(), request)
		if err != nil || step.Kind != kind {
			t.Fatalf("step = %+v, %v; want %s", step, err, kind)
		}
	}
	volumes.attachments[0].State = "DETACHED"
	for _, kind := range []StepKind{StepAttach, StepWaitAttached} {
		step, err := reattacher.Step(t.Context(), request)
		if err != nil || step.Kind != kind {
			t.Fatalf("step = %+v, %v; want %s", step, err, kind)
		}
	}
	volumes.attachments[1].State = "ATTACHED"
	for _, kind := range []StepKind{StepGrantMount, StepDone} {
		step, err := reattacher.Step(t.Context(), request)
		if err != nil || step.Kind != kind {
			t.Fatalf("step = %+v, %v; want %s", step, err, kind)
		}
	}
	if volumes.detaches != 1 || volumes.attaches != 1 || len(permits.granted) != 1 {
		t.Fatalf("effects detach=%d attach=%d permits=%v", volumes.detaches, volumes.attaches, permits.granted)
	}
	for _, proof := range volumes.proofs {
		if proof.InstanceID != "old" || proof.State != "TERMINATED" {
			t.Fatalf("effect ran without terminated proof: %+v", proof)
		}
	}
}

func TestReattacherRefusesFollowerFencedAndForeignAttachments(t *testing.T) {
	volumes := &fakeVolumes{attachments: []Attachment{attachment("a", "old", "ATTACHED")}}
	base := Reattacher{Fencer: &fakeFencer{snapshot: leader()},
		Instances: fakeInstances{"old": "TERMINATED"}, Volumes: volumes, Permits: &fakePermits{granted: map[string]bool{}}}

	follower := base
	follower.Fencer = &fakeFencer{snapshot: authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Ready: true}}
	if _, err := follower.Step(t.Context(), request); !errors.Is(err, authority.ErrNotLeader) {
		t.Fatalf("follower reattached: %v", err)
	}
	fenced := base
	fenced.Fencer = &fakeFencer{snapshot: leader(), guardErr: authority.ErrFenced}
	if _, err := fenced.Step(t.Context(), request); !errors.Is(err, authority.ErrFenced) {
		t.Fatalf("fenced leader reattached: %v", err)
	}
	same := request
	same.ReplacementInstanceID = same.OldInstanceID
	if _, err := base.Step(t.Context(), same); err == nil {
		t.Fatal("reattach to the lost instance itself was accepted")
	}
	volumes.attachments = []Attachment{attachment("c", "third", "ATTACHED")}
	if step, err := base.Step(t.Context(), request); step.Kind != StepHold || !errors.Is(err, storage.ErrVolumeHeld) || errors.Is(err, storage.ErrVolumeStuck) {
		t.Fatalf("foreign attachment did not hold: %+v %v", step, err)
	}
	if volumes.detaches != 0 || volumes.attaches != 0 {
		t.Fatalf("refused reattach performed effects: detach=%d attach=%d", volumes.detaches, volumes.attaches)
	}
}

func TestReattacherSeparatesFailedLookupsAndBindsTheExpectedEpoch(t *testing.T) {
	volumes := &fakeVolumes{attachments: []Attachment{attachment("a", "old", "ATTACHED")}}
	permits := &fakePermits{granted: map[string]bool{}}
	reattacher := Reattacher{Fencer: &fakeFencer{snapshot: leader()},
		Instances: fakeInstances{}, Volumes: volumes, Permits: permits}
	step, err := reattacher.Step(t.Context(), request)
	if step.Kind != StepProveFence || !errors.Is(err, ErrFenceUnobserved) || !errors.Is(err, storage.ErrWriterNotFenced) {
		t.Fatalf("failed lookup: %+v %v", step, err)
	}
	reattacher.Instances = fakeInstances{"old": "STOPPED"}
	if _, err := reattacher.Step(t.Context(), request); errors.Is(err, ErrFenceUnobserved) {
		t.Fatalf("an observed STOPPED state was reported as a failed lookup: %v", err)
	}
	reattacher.Instances = fakeInstances{"old": "TERMINATED"}
	reattacher.ExpectedEpoch = leader().Epoch + 1
	if _, err := reattacher.Step(t.Context(), request); !errors.Is(err, authority.ErrFenced) || volumes.detaches != 0 || volumes.listings != 0 {
		t.Fatalf("stale expected epoch: %v detaches=%d listings=%d", err, volumes.detaches, volumes.listings)
	}
	reattacher.ExpectedEpoch = leader().Epoch
	if step, err := reattacher.Step(t.Context(), request); err != nil || step.Kind != StepDetach || volumes.detaches != 1 {
		t.Fatalf("current expected epoch: %+v %v detaches=%d", step, err, volumes.detaches)
	}
}

func TestBlockDeviceMountedMatchesExactDevice(t *testing.T) {
	path := filepath.Join(t.TempDir(), "mountinfo")
	if err := os.WriteFile(path, []byte(mountInfo), 0o600); err != nil {
		t.Fatal(err)
	}
	for rdev, want := range map[uint64]bool{unix.Mkdev(8, 16): true, unix.Mkdev(8, 32): true, unix.Mkdev(8, 48): false, unix.Mkdev(8, 1): true} {
		if got, err := BlockDeviceMounted(path, rdev); err != nil || got != want {
			t.Fatalf("BlockDeviceMounted(%d:%d) = %v, %v; want %v", unix.Major(rdev), unix.Minor(rdev), got, err, want)
		}
	}
}

func TestBtrfsRootExcludesEveryKernelMember(t *testing.T) {
	sysRoot := t.TempDir()
	const uuid = "0d370616-bf07-48e3-90a4-75e58c799c01"
	root := filepath.Join(sysRoot, "fs/btrfs", uuid)
	var want []string
	for i, device := range []string{"8:1", "8:17"} {
		name := "disk" + strconv.Itoa(i)
		whole := filepath.Join(sysRoot, "devices/block", name)
		partition := filepath.Join(whole, name+"1")
		for _, directory := range []string{partition, filepath.Join(sysRoot, "dev/block"), filepath.Join(root, "devices", name), filepath.Join(root, "devinfo", strconv.Itoa(i+1))} {
			if err := os.MkdirAll(directory, 0o755); err != nil {
				t.Fatal(err)
			}
		}
		if err := os.WriteFile(filepath.Join(partition, "partition"), []byte("1\n"), 0o444); err != nil {
			t.Fatal(err)
		}
		if err := os.Symlink(partition, filepath.Join(sysRoot, "dev/block", device)); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(root, "devices", name, "dev"), []byte(device+"\n"), 0o444); err != nil {
			t.Fatal(err)
		}
		for field, value := range map[string]string{"missing": "0", "in_fs_metadata": "1", "replace_target": "0", "fsid": uuid} {
			if err := os.WriteFile(filepath.Join(root, "devinfo", strconv.Itoa(i+1), field), []byte(value+"\n"), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		want = append(want, whole)
	}
	got, err := btrfsRootDevices(sysRoot, unix.Mkdev(8, 1))
	if err != nil || !reflect.DeepEqual(got, want) {
		t.Fatalf("complete root disks: %v, %v; want %v", got, err, want)
	}
	for field, unsafe := range map[string]string{"missing": "1", "in_fs_metadata": "0", "replace_target": "1", "fsid": "another-filesystem"} {
		t.Run(field, func(t *testing.T) {
			path := filepath.Join(root, "devinfo/2", field)
			original, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(path, []byte(unsafe), 0o644); err != nil {
				t.Fatal(err)
			}
			defer os.WriteFile(path, original, 0o644)
			if _, err := btrfsRootDevices(sysRoot, unix.Mkdev(8, 1)); err == nil {
				t.Fatal("incomplete or changing root membership accepted")
			}
		})
	}
	if err := os.Remove(filepath.Join(sysRoot, "dev/block/8:17")); err != nil {
		t.Fatal(err)
	}
	if _, err := btrfsRootDevices(sysRoot, unix.Mkdev(8, 1)); err == nil {
		t.Fatal("unresolvable second root member accepted")
	}
}

func TestExt4ResizeBlocks(t *testing.T) {
	blocks, err := Ext4ResizeBlocks(100<<30+123, 4096)
	if err != nil || blocks != (100<<30)/4096 {
		t.Fatalf("blocks = %d, %v", blocks, err)
	}
	for _, size := range []uint64{0, 512, 3000, 1 << 17} {
		if _, err := Ext4ResizeBlocks(1<<30, size); err == nil {
			t.Fatalf("block size %d accepted", size)
		}
	}
	if _, err := Ext4ResizeBlocks(1000, 4096); err == nil {
		t.Fatal("device smaller than a block accepted")
	}
}

func TestFilesystemData(t *testing.T) {
	if FilesystemData("ext4") != "errors=remount-ro" || FilesystemData("xfs") != "" {
		t.Fatal("unexpected filesystem mount data")
	}
}

func TestFormatCommandPinsUUIDAndSupportsXFS(t *testing.T) {
	uuid := "123e4567-e89b-12d3-a456-426614174000"
	tool, args, err := FormatCommand("ext4", uuid)
	if err != nil || tool != "/usr/sbin/mkfs.ext4" || !slices.Contains(args, uuid) {
		t.Fatalf("ext4 command = %s %v, %v", tool, args, err)
	}
	tool, args, err = FormatCommand("xfs", uuid)
	if err != nil || tool != "/usr/sbin/mkfs.xfs" || !slices.Contains(args, "uuid="+uuid) {
		t.Fatalf("xfs command = %s %v, %v", tool, args, err)
	}
	for _, bad := range []struct{ fs, uuid string }{
		{"btrfs", uuid},
		{"ext4", "123E4567-E89B-12D3-A456-426614174000"},
		{"ext4", "not-a-uuid"},
		{"xfs", uuid + "0"},
		{"ext4", "123e4567-e89b-12d3-a456-42661417400g"},
	} {
		if _, _, err := FormatCommand(bad.fs, bad.uuid); err == nil {
			t.Fatalf("FormatCommand(%q, %q) accepted", bad.fs, bad.uuid)
		}
	}
}

func TestGrowNeededIgnoresSmallTailsAndNeverShrinks(t *testing.T) {
	const block = 4096
	fsBlocks := uint64(50<<30) / block
	if GrowNeeded(50<<30, fsBlocks, block, 128<<20) {
		t.Fatal("equal sizes need growth")
	}
	if GrowNeeded(50<<30+64<<20, fsBlocks, block, 128<<20) {
		t.Fatal("small tail triggered growth")
	}
	if !GrowNeeded(100<<30, fsBlocks, block, 128<<20) {
		t.Fatal("doubled device did not need growth")
	}
	if GrowNeeded(40<<30, fsBlocks, block, 128<<20) {
		t.Fatal("smaller device requested growth")
	}
	if GrowNeeded(100<<30, fsBlocks, 0, 0) {
		t.Fatal("zero block size requested growth")
	}
}

func TestGrowSlackTriggersOnEveryWholeGiBResize(t *testing.T) {
	const block = 4096
	// XFS reports roughly 0.3% and ext4 up to about 2% of the device as
	// metadata overhead below statfs blocks; a 1 GiB resize must still clear
	// the gate on large volumes.
	for _, size := range []uint64{50 << 30, 64 << 30, 1 << 40} {
		fsBlocks := (size - size/50) / block
		if !GrowNeeded(size+1<<30, fsBlocks, block, GrowSlack) {
			t.Fatalf("a +1 GiB resize of a %d GiB volume did not trigger growth", size>>30)
		}
	}
	if GrowNeeded(50<<30, (50<<30-200<<20)/block, block, GrowSlack) {
		t.Fatal("metadata overhead of an unresized small volume triggered growth")
	}
}

func TestMountOptionsSelectsExactMountID(t *testing.T) {
	options, err := MountOptions(strings.NewReader(mountInfo), 31)
	if err != nil || options != "rw,nosuid,nodev,noexec,noatime" {
		t.Fatalf("mount 31 options = %q, %v", options, err)
	}
	if _, err := MountOptions(strings.NewReader(mountInfo), 99); err == nil {
		t.Fatal("missing mount ID was found")
	}
	if _, err := MountOptions(strings.NewReader("x 1 8:1 / / rw - ext4 /dev/sda rw\n"), 1); err == nil {
		t.Fatal("corrupt mountinfo was accepted")
	}
}

func TestOptionsHardenedRequiresEveryFlag(t *testing.T) {
	cases := map[string]bool{
		"rw,nosuid,nodev,noexec,noatime":  true,
		"rw,noexec,nodev,nosuid,noatime":  true,
		"rw,noexec,nodev,nosuid":          false,
		"rw,nosuid,nodev,noexec,relatime": false,
		"rw,nosuid,nodev":                 false,
		"rw,relatime":                     false,
		"":                                false,
		"rw,nosuidx,nodev,noexec":         false,
	}
	for options, want := range cases {
		if got := OptionsHardened(options); got != want {
			t.Fatalf("OptionsHardened(%q) = %v, want %v", options, got, want)
		}
	}
}

func TestRequireHardenedReadsMountInfoFile(t *testing.T) {
	path := filepath.Join(t.TempDir(), "mountinfo")
	if err := os.WriteFile(path, []byte(mountInfo), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := RequireHardened(path, 31); err != nil {
		t.Fatalf("hardened mount rejected: %v", err)
	}
	if err := RequireHardened(path, 32); err == nil {
		t.Fatal("unhardened mount accepted")
	}
}

func TestSysfsDeviceBytesReadsSectors(t *testing.T) {
	root := t.TempDir()
	node := filepath.Join(root, "dev", "block", "8:16")
	if err := os.MkdirAll(node, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(node, "size"), []byte("104857600\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if size, err := SysfsDeviceBytes(root, 8, 16); err != nil || size != 50<<30 {
		t.Fatalf("size = %d, %v; want 50 GiB", size, err)
	}
	if _, err := SysfsDeviceBytes(root, 8, 32); err == nil {
		t.Fatal("missing device reported a size")
	}
	for _, bad := range []string{"0", "garbage", "-1"} {
		if err := os.WriteFile(filepath.Join(node, "size"), []byte(bad), 0o644); err != nil {
			t.Fatal(err)
		}
		if _, err := SysfsDeviceBytes(root, 8, 16); err == nil {
			t.Fatalf("size %q was accepted", bad)
		}
	}
}

func TestContainerMountFixture(t *testing.T) {
	if os.Getenv("TS_VOLUME_OBSERVER_FIXTURE") != "container" {
		return
	}
	root, source := os.Getenv("TS_VOLUME_OBSERVER_ROOT"), os.Getenv("TS_VOLUME_OBSERVER_SOURCE")
	if err := unix.Mount("", "/", "", unix.MS_REC|unix.MS_PRIVATE, ""); err != nil {
		t.Fatal(err)
	}
	if err := unix.Mount(source, filepath.Join(root, "retained"), "", unix.MS_BIND, ""); err != nil {
		t.Fatal(err)
	}
	if err := HardenRemount(filepath.Join(root, "retained")); err != nil {
		t.Fatal(err)
	}
	if err := unix.Chroot(root); err != nil {
		t.Fatal(err)
	}
	if err := os.Chdir("/"); err != nil {
		t.Fatal(err)
	}
	fmt.Println("ready")
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		if scanner.Text() != "shadow" {
			t.Fatal("unknown fixture command")
		}
		if err := unix.Mount("/retained", "/alias", "", unix.MS_BIND, ""); err != nil {
			t.Fatal(err)
		}
		fmt.Println("shadowed")
	}
}

func TestRetainedMountKernelIntegration(t *testing.T) {
	if os.Getenv("TS_VOLUME_OBSERVER_FIXTURE") != "mount" {
		executable, err := os.Executable()
		if err != nil {
			t.Fatal(err)
		}
		command := exec.Command("sudo", "-n", "env", "TS_VOLUME_OBSERVER_FIXTURE=mount", "nice", "-n", "19", "unshare", "--mount", executable, "-test.run=^TestRetainedMountKernelIntegration$", "-test.v")
		output, err := command.CombinedOutput()
		if err != nil {
			t.Fatalf("real block/mount fixture: %v\n%s", err, output)
		}
		t.Log(string(output))
		return
	}
	if err := unix.Mount("", "/", "", unix.MS_REC|unix.MS_PRIVATE, ""); err != nil {
		t.Fatal(err)
	}
	directory, err := os.MkdirTemp("/run", "ts-data-volume-")
	if err != nil {
		t.Fatal(err)
	}
