decision_record.text:
// Default returns the installed recorder, or nil when records go to the log.
func Default() Recorder {
	if holder := defaultRecorder.Load(); holder != nil {
		return holder.recorder
	}
	return nil
}

// Record journals one decision with the process-wide recorder and returns
// its ID, so a caller can link later decisions to it with ParentID. It never
// blocks on the network and never fails; see the package documentation.
func Record(ctx context.Context, decision Decision) string {
	if recorder := Default(); recorder != nil {
		return recorder.Record(ctx, decision)
	}
	return LogRecorder{}.Record(ctx, decision)
}

// LogRecorder writes decisions to the default structured logger. It is the
// fallback before a Journal is installed, and the recorder of processes
// without a regional stream (one-shot CLI commands, hosts).
type LogRecorder struct {
	Logger *slog.Logger
}

// Record logs the decision and returns its ID.
func (recorder LogRecorder) Record(ctx context.Context, decision Decision) string {
	decision = decision.Normalize(time.Now())
	logger := recorder.Logger
	if logger == nil {
		logger = slog.Default()
	}
	attrs := []slog.Attr{slog.String(observability.ComponentKey, "decision"), slog.Bool(observability.EventKey, true),
		slog.String("decision_id", decision.ID),
		slog.String("kind", string(decision.Kind)), slog.String("actor", decision.Actor.Slice),
		slog.String("subject", decision.Subject.String()), slog.String("status", string(decision.Status))}
	if decision.Region != "" {
		attrs = append(attrs, slog.String("region", decision.Region))
	}
	if decision.Reason != "" {
		attrs = append(attrs, slog.String("reason", decision.Reason))
	}
	if decision.ParentID != "" {
		attrs = append(attrs, slog.String("parent_id", decision.ParentID))
	}
	logger.LogAttrs(ctx, slog.LevelInfo, decision.Summary, attrs...)
	return decision.ID
}

decision_correlation.text:
// maxCorrelations bounds the process-wide correlation table.
const maxCorrelations = 4096

// correlations maps a caller-chosen key (for example "release:sha256:..." or
// "managed_update:<operation>") to the ID of the decision that started that
// chain in this process, so a later decision by another slice can name it as
// its parent without both slices sharing state.
var correlations = struct {
	sync.Mutex
	ids   map[string]string
	order []string
}{ids: map[string]string{}}

// Correlate remembers id as the decision for key. The table is bounded;
// the oldest keys are forgotten first.
func Correlate(key, id string) {
	if key == "" || id == "" {
		return
	}
	correlations.Lock()
	defer correlations.Unlock()
	if _, exists := correlations.ids[key]; !exists {
		correlations.order = append(correlations.order, key)
	}
	correlations.ids[key] = id
	for len(correlations.order) > maxCorrelations {
		delete(correlations.ids, correlations.order[0])
		correlations.order = correlations.order[1:]
	}
}

// Correlated returns the decision ID remembered for key, or "".
func Correlated(key string) string {
	correlations.Lock()
	defer correlations.Unlock()
	return correlations.ids[key]
}

options.text:
var HardenedOptions = []string{"nosuid", "nodev", "noexec", "noatime"}

// OptionsHardened reports whether a mountinfo per-mount option field (for
// example "rw,nosuid,nodev,noexec,noatime") carries every hardened option.
func OptionsHardened(options string) bool {
	present := make(map[string]bool)
	for _, option := range strings.Split(options, ",") {
		present[option] = true
	}
	for _, required := range HardenedOptions {
		if !present[required] {
			return false
		}
	}
	return true
}

// MountOptions returns the per-mount option field of mountID from a
// /proc/self/mountinfo formatted reader.
func MountOptions(mountInfo io.Reader, mountID uint64) (string, error) {
	scanner := bufio.NewScanner(mountInfo)
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) < 6 {
			continue
		}
		id, err := strconv.ParseUint(fields[0], 10, 64)
		if err != nil {
			return "", fmt.Errorf("parse mountinfo ID: %w", err)
		}
		if id == mountID {
			return fields[5], nil
		}
	}
	if err := scanner.Err(); err != nil {
		return "", err
	}
	return "", fmt.Errorf("mount %d is not visible", mountID)
}

// RequireHardened fails unless mountID in mountInfoPath carries every
// hardened option.
func RequireHardened(mountInfoPath string, mountID uint64) error {
	file, err := os.Open(mountInfoPath)
	if err != nil {
		return err
	}
	defer file.Close()
	options, err := MountOptions(file, mountID)
	if err != nil {
		return err
	}
	if !OptionsHardened(options) {
		return fmt.Errorf("managed volume mount lacks %s", strings.Join(HardenedOptions, ","))
	}
	return nil
}

format.text:
func FilesystemData(fsType string) string {
	if fsType == storage.FileSystemExt4 {
		return "errors=remount-ro"
	}
	return ""
}

// FormatCommand returns the fixed absolute mkfs tool and arguments that create
// fsType with the signed UUID. The pinned device is appended by the caller.
func FormatCommand(fsType, uuid string) (string, []string, error) {
	if !ValidUUID(uuid) {
		return "", nil, errors.New("managed filesystem UUID is invalid")
	}
	switch fsType {
	case storage.FileSystemExt4:
		return "/usr/sbin/mkfs.ext4", []string{"-F", "-U", uuid, "-m", "0", "-E", "lazy_itable_init=0,lazy_journal_init=0"}, nil
	case storage.FileSystemXFS:
		return "/usr/sbin/mkfs.xfs", []string{"-f", "-m", "uuid=" + uuid}, nil
	default:
		return "", nil, fmt.Errorf("managed filesystem type %q is unsupported", fsType)
	}
}

// Ext4ResizeBlocks returns the block count passed to EXT4_IOC_RESIZE_FS for a
// device of deviceBytes and a filesystem block size. The kernel treats an
// unchanged count as a no-op and rejects shrinking, so growth stays one-way.
func Ext4ResizeBlocks(deviceBytes, blockSize uint64) (uint64, error) {
	if blockSize < 1024 || blockSize > 65536 || blockSize&(blockSize-1) != 0 {
		return 0, errors.New("ext4 block size is invalid")
	}
	if deviceBytes < blockSize {
		return 0, errors.New("managed block device is smaller than one filesystem block")
	}
	return deviceBytes / blockSize, nil
}

sysfs.text:
func SysfsDeviceBytes(sysRoot string, major, minor uint32) (uint64, error) {
	data, err := os.ReadFile(filepath.Join(sysRoot, "dev", "block", fmt.Sprintf("%d:%d", major, minor), "size"))
	if err != nil {
		return 0, fmt.Errorf("read managed block device size: %w", err)
	}
	sectors, err := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
	if err != nil || sectors == 0 || sectors > math.MaxUint64/512 {
		return 0, errors.New("managed block device size is invalid")
	}
	return sectors * 512, nil
}

// GrowNeeded reports whether a filesystem of fsBlocks*blockSize bytes can grow
// by at least one block group's worth of space (minSlack) on deviceBytes.
// Small tails left by alignment never trigger a resize.
func GrowNeeded(deviceBytes, fsBlocks, blockSize, minSlack uint64) bool {
	if blockSize == 0 || fsBlocks > deviceBytes/blockSize {
		return false
	}
	return deviceBytes-fsBlocks*blockSize >= minSlack
}

// ValidUUID accepts only a canonical lowercase filesystem UUID.
func ValidUUID(value string) bool {
	if len(value) != 36 {
		return false
	}
	for index, character := range value {
		switch index {
		case 8, 13, 18, 23:
			if character != '-' {
				return false
			}
		default:
			if !strings.ContainsRune("0123456789abcdef", character) {
				return false
			}
		}
	}
	return true
}

